from datetime import datetime, timedelta
from pathlib import Path
import tempfile
import unittest
from unittest.mock import patch

import api_server
import categories
import config
import database
import starter_catalogue
import training_catalogue


class StarterUpgradeTests(unittest.TestCase):
    """Use disposable synthetic catalogues with a real file-backed occupied runtime."""

    def setUp(self):
        """Build one stable course with three original and two additional occurrences."""
        temporary = tempfile.TemporaryDirectory(prefix='weekwise-upgrade-test-')
        self.addCleanup(temporary.cleanup)
        self.directory = Path(temporary.name)
        self.seed_path = self.directory / 'extended.sqlite'
        self.target_path = self.directory / 'working.sqlite'
        self.source = database.get_connection(':memory:')
        self.target = database.get_connection(self.target_path)
        self.seed = database.get_connection(self.seed_path)
        for connection in (self.source, self.target, self.seed):
            self.addCleanup(connection.close)
            database.init_db(connection)
        categories.seed_categories(self.source, categories.load_taxonomy())
        bundle = self.source.execute('SELECT id FROM bundles WHERE key=?',
                                     ('sports_racket',)).fetchone()[0]
        with self.source:
            self.source.execute('''INSERT INTO series
                (id,source,external_id,title,description,organizer,bundle_id,sport,
                 location_type,source_url,is_recurring)
                VALUES (1,'unisport','history-pattern:1','Synthetic tennis',
                        ?,'Unisport HSG',?,'Synthetic tennis','tba',?,1)''',
                (config.TRAINING_CATALOGUE_DESCRIPTION, bundle,
                 config.UNISPORT_PUBLIC_SCHEDULE_URL))
        self.add_occurrences(1, 3)
        approvals = [{'external_id': 'history-pattern:1', 'product_id': 71,
                      'public_title': 'Synthetic tennis', 'appointment_description': ''}]
        self.old_id = training_catalogue.build_training_catalogue(
            self.source, self.target, approvals)['catalogue_id']
        self.add_occurrences(4, 5)
        self.new_id = training_catalogue.build_training_catalogue(
            self.source, self.seed, approvals)['catalogue_id']
        for name, value in (('PREDECESSOR_ID', self.old_id), ('PREDECESSOR_EVENTS', 3),
                            ('PREDECESSOR_COURSES', 1)):
            patcher = patch.object(starter_catalogue, name, value)
            patcher.start()
            self.addCleanup(patcher.stop)

    def add_occurrences(self, first, last):
        """Append weekly synthetic slots and their explicit projection evidence."""
        with self.source:
            for event_id in range(first, last + 1):
                start = datetime(2026, 11, 16, 7) + timedelta(weeks=event_id - 1)
                self.source.execute('''INSERT INTO events
                    (id,series_id,start_time,end_time,end_is_estimated,status)
                    VALUES (?,1,?,?,1,'unknown')''',
                    (event_id, database.to_db_text(start),
                     database.to_db_text(start + timedelta(minutes=90))))
                self.source.execute('''INSERT INTO event_provenance
                    (event_id,kind,forecast_anchor_date,evidence_weeks,created_at)
                    VALUES (?,'projected','2026-11-06',3,'2026-11-15 09:00:00')''',
                    (event_id,))

    def bootstrap(self):
        """Request an enabled upgrade from the synthetic extended public file."""
        return starter_catalogue.bootstrap_starter(self.target, self.seed_path, enabled=True)

    def dump(self):
        """Snapshot all existing schema and values for failed-upgrade assertions."""
        return list(self.target.iterdump())

    def add_local_planning(self):
        """Make existing profile, planning, ownership and manual corrections observable."""
        user_id = database.create_user(self.target, 'Synthetic student',
                                       now=datetime(2026, 11, 17, 12))
        with self.target:
            self.target.execute('''INSERT INTO favorites
                (user_id,kind,target_id,created_at) VALUES (?,'series',1,?)''',
                (user_id, '2026-11-17 12:00:00'))
            self.target.execute('''INSERT INTO interactions
                (user_id,event_id,status,confirmed_at) VALUES (?,1,'confirmed',?)''',
                (user_id, '2026-11-17 12:00:00'))
            self.target.execute('UPDATE series SET title=? WHERE id=?',
                                ('Local course correction', 1))
            self.target.execute('UPDATE events SET end_time=?,status=? WHERE id=?',
                                ('2026-11-16 09:00:00', 'open', 1))
            self.target.execute('UPDATE event_provenance SET created_at=? WHERE event_id=?',
                                ('2026-11-16 10:00:00', 1))
            self.target.execute('INSERT INTO app_settings (key,value) VALUES (?,?)',
                                (config.UNICLUBS_PROFILE_SETTING_PREFIX + str(user_id),
                                 'synthetic-private-owner'))
        return user_id

    def test_upgrade_preserves_every_existing_value_except_catalogue_marker(self):
        """Extending a populated runtime keeps profiles, plans and manual corrections intact."""
        self.add_local_planning()
        old = self.dump()
        seed_bytes = self.seed_path.read_bytes()
        self.assertTrue(self.bootstrap())
        self.assertEqual(database.get_catalogue_id(self.target), self.new_id)
        self.assertEqual(self.target.execute('SELECT COUNT(*) FROM events').fetchone()[0], 5)
        with self.target:
            self.target.execute('DELETE FROM event_provenance WHERE event_id>?', (3,))
            self.target.execute('DELETE FROM events WHERE id>?', (3,))
            self.target.execute('UPDATE app_settings SET value=? WHERE key=?',
                                (self.old_id, 'catalogue_id'))
        self.assertEqual(self.dump(), old)
        self.assertEqual(self.seed_path.read_bytes(), seed_bytes)

    def test_replay_is_a_true_noop(self):
        """After the catalogue marker advances, another startup changes no values."""
        self.assertTrue(self.bootstrap())
        before = self.dump()
        self.assertFalse(self.bootstrap())
        self.assertEqual(self.dump(), before)

    def test_unknown_predecessor_is_preserved_without_upgrade(self):
        """A different reviewed dataset is never interpreted as this release's predecessor."""
        with self.target:
            self.target.execute('UPDATE app_settings SET value=? WHERE key=?',
                                ('reviewed-other-dataset', 'catalogue_id'))
        before = self.dump()
        self.assertFalse(self.bootstrap())
        self.assertEqual(self.dump(), before)

    def test_old_identity_and_missing_proof_are_rejected_atomically(self):
        """Conflicting original identities cannot receive more rows under a trusted marker."""
        with self.target:
            self.target.execute('UPDATE series SET external_id=? WHERE id=?',
                                ('history-pattern:999', 1))
        before = self.dump()
        with self.assertRaises(ValueError):
            self.bootstrap()
        self.assertEqual(self.dump(), before)
        with self.target:
            self.target.execute('UPDATE series SET external_id=? WHERE id=?',
                                ('history-pattern:1', 1))
            self.target.execute('DELETE FROM event_provenance WHERE event_id=?', (2,))
        before = self.dump()
        with self.assertRaises(ValueError):
            self.bootstrap()
        self.assertEqual(self.dump(), before)

    def test_new_primary_key_collision_is_rejected_atomically(self):
        """An occupied incoming ID must not replace an unrelated locally added slot."""
        with self.target:
            self.target.execute('''INSERT INTO events
                (id,series_id,start_time,end_time,end_is_estimated,status)
                VALUES (4,1,'2027-01-01 07:00:00','2027-01-01 08:00:00',0,'open')''')
        before = self.dump()
        with self.assertRaises(ValueError):
            self.bootstrap()
        self.assertEqual(self.dump(), before)

    def test_changed_original_start_is_rejected_without_touching_local_correction(self):
        """A moved original slot cannot silently receive new dates under a stale identity."""
        with self.target:
            self.target.execute('UPDATE events SET start_time=? WHERE id=?',
                                ('2026-11-16 07:15:00', 1))
        before = self.dump()
        with self.assertRaises(ValueError):
            self.bootstrap()
        self.assertEqual(self.dump(), before)

    def test_new_unique_slot_collision_is_rejected_atomically(self):
        """An existing slot with a different ID cannot be silently rebound to an incoming ID."""
        incoming = self.seed.execute('SELECT start_time,end_time FROM events WHERE id=?',
                                     (4,)).fetchone()
        with self.target:
            self.target.execute('''INSERT INTO events
                (id,series_id,start_time,end_time,end_is_estimated,status)
                VALUES (99,1,?,?,0,'open')''', tuple(incoming))
        before = self.dump()
        with self.assertRaises(ValueError):
            self.bootstrap()
        self.assertEqual(self.dump(), before)

    def test_late_write_failure_rolls_back_insertions_and_marker(self):
        """A failure after inserting new events cannot leave a half-applied catalogue."""
        before = self.dump()
        original = starter_catalogue._append_occurrences

        def fail_after_append(connection, events, proofs):
            """Exercise the actual writes before injecting an ordinary validation failure."""
            original(connection, events, proofs)
            raise ValueError('Synthetic failure after append')

        with patch.object(starter_catalogue, '_append_occurrences', fail_after_append):
            with self.assertRaises(ValueError):
                self.bootstrap()
        self.assertEqual(self.dump(), before)
        self.assertFalse(self.target.in_transaction)

    def test_changed_incoming_content_is_rejected_before_writes(self):
        """The advertised new marker cannot authorize changed incoming event content."""
        with self.seed:
            self.seed.execute('UPDATE events SET end_time=? WHERE id=?',
                              ('2026-12-14 10:00:00', 5))
        before = self.dump()
        with self.assertRaises(ValueError):
            self.bootstrap()
        self.assertEqual(self.dump(), before)

    def test_private_incoming_data_is_rejected_before_writes(self):
        """A valid lineage never permits profile data to enter the public source."""
        database.create_user(self.seed, 'Private fixture',
                             now=datetime(2026, 11, 17, 12))
        before = self.dump()
        with self.assertRaises(ValueError):
            self.bootstrap()
        self.assertEqual(self.dump(), before)

    def test_modified_incoming_prefix_or_fingerprint_is_rejected(self):
        """A valid public schema alone does not authorize changing the published predecessor."""
        before = self.dump()
        with self.seed:
            self.seed.execute('UPDATE events SET end_time=? WHERE id=?',
                              ('2026-11-16 10:00:00', 1))
            # A freshly recomputed full hash still cannot authorize rewriting the old prefix.
            courses, events, proofs = starter_catalogue._catalogue_rows(self.seed)
            changed_id = training_catalogue._catalogue_id(
                courses, events, proofs, categories.load_taxonomy())
            self.seed.execute('UPDATE app_settings SET value=? WHERE key=?',
                              (changed_id, 'catalogue_id'))
        with self.assertRaises(ValueError):
            self.bootstrap()
        self.assertEqual(self.dump(), before)

    def test_api_first_upgrade_serves_added_dates_with_new_identity(self):
        """The API startup hook exposes new dates before Streamlit has run."""
        with patch.object(config, 'PUBLIC_UNISPORT_SEED', self.seed_path), \
                patch.object(config, 'USE_PUBLIC_STARTER', True):
            api_server.prepare_database(self.target_path)
        client = api_server.create_app(self.target_path).test_client()
        response = client.get('/events', query_string={'from': '2026-12-07',
                                                       'to': '2026-12-15'})
        self.assertEqual(response.status_code, 200)
        self.assertEqual(len(response.json), 2)
        self.assertEqual(response.headers[config.API_CATALOGUE_HEADER], self.new_id)


if __name__ == '__main__':
    unittest.main()
